**State Transitions:**

```rust
impl SessionState {
    fn transition(&mut self, new_state: SessionStateEnum) -> SessionStateEnum {
        if new_state != self.current_state {
            info!(
                "Session {} transitioning from {:?} to {:?}",
                self.session_id, self.current_state, new_state
            );

            self.current_state = new_state;
            self.state_entered_at = Utc::now();
            self.metadata.escalation_count += 1;

            // Persist to DB
            self.save_to_db();
        }

        new_state
    }

    fn evaluate_transitions(&mut self) -> SessionStateEnum {
        match self.current_state {
            SessionStateEnum::Normal => {
                if self.has_rapid_fire_pattern() || self.has_privilege_escalation() {
                    self.transition(SessionStateEnum::Elevated)
                } else {
                    SessionStateEnum::Normal
                }
            },

            SessionStateEnum::Elevated => {
                if self.has_exfiltration_pattern() || self.has_lateral_movement() {
                    self.transition(SessionStateEnum::Suspicious)
                } else if self.is_calm_for(Duration::from_secs(300)) {
                    // De-escalate after 5 min of normal behavior
                    self.transition(SessionStateEnum::Normal)
                } else {
                    SessionStateEnum::Elevated
                }
            },

            SessionStateEnum::Suspicious => {
                if self.has_confirmed_attack_pattern() {
                    self.transition(SessionStateEnum::Blocked)
                } else if self.is_calm_for(Duration::from_secs(600)) {
                    self.transition(SessionStateEnum::Elevated)
                } else {
                    SessionStateEnum::Suspicious
                }
            },

            SessionStateEnum::Blocked => {
                // Manual unblock only (or automatic after 24h)
                if self.state_entered_at + Duration::from_secs(86400) < Utc::now() {
                    self.transition(SessionStateEnum::Normal)
                } else {
                    SessionStateEnum::Blocked
                }
            },
        }
    }
}
