### 3.2 Detection Patterns

**Pattern 1: Rapid-Fire Enumeration**

Attacker attempts to enumerate files/resources rapidly.

```rust
fn has_rapid_fire_pattern(&self) -> bool {
    let window = Duration::from_secs(10);
    let recent_events: Vec<_> = self.events.iter()
        .filter(|e| e.timestamp > Utc::now() - window)
        .collect();

    // More than 20 tool calls in 10 seconds
    if recent_events.len() > 20 {
        // Check if they're similar (e.g., repeated file reads)
        let unique_tools: HashSet<_> = recent_events.iter()
            .map(|e| &e.tool_name)
            .collect();

        // If < 3 unique tools, likely enumeration
        return unique_tools.len() < 3;
    }

    false
}
```

**Pattern 2: Privilege Escalation Chain**

Sequence: read sensitive file → modify config → restart service

```rust
fn has_privilege_escalation(&self) -> bool {
    let window = Duration::from_secs(60);
    let recent: Vec<_> = self.events.iter()
        .filter(|e| e.timestamp > Utc::now() - window)
        .collect();

    // Look for sequence: file_read (sensitive) → file_write (config) → shell_exec (restart)
    let mut seen_sensitive_read = false;
    let mut seen_config_write = false;

    for event in recent {
        if event.tool_name == "file_read" && self.is_sensitive_path(&event) {
            seen_sensitive_read = true;
        }
        if seen_sensitive_read && event.tool_name == "file_write" && self.is_config_path(&event) {
            seen_config_write = true;
        }
        if seen_config_write && event.tool_name == "shell_exec" {
            return true;  // Full chain detected
        }
    }

    false
}

fn is_sensitive_path(&self, event: &ToolCallEvent) -> bool {
    // Check if event involved /etc/passwd, .ssh/*, .env, etc.
    // (would need to inspect event.arguments_hash against known patterns)
    self.metadata.sensitive_tools_used.contains("file_read_sensitive")
}
