        (PIIType::SSN, Regex::new(r"\b\d{3}-\d{2}-\d{4}\b").unwrap()),
        (PIIType::CreditCard, Regex::new(r"\b\d{4}[-\s]?\d{4}[-\s]?\d{4}[-\s]?\d{4}\b").unwrap()),
