fn detect_pii(text: &str) -> Vec<PIIDetection> {
    let mut detections = Vec::new();

    for (pii_type, pattern) in PII_PATTERNS.iter() {
        for capture in pattern.captures_iter(text) {
            let value = capture.get(0).unwrap().as_str();

            // Validate (e.g., Luhn algorithm for credit cards)
            if validate_pii(pii_type, value) {
                detections.push(PIIDetection {
                    pii_type: pii_type.clone(),
                    value: redact_value(value),
                    location: "arguments".to_string(),
                    confidence: 0.95,
                });
            }
        }
    }

    detections
}

