### 4.2 Async Hold Mechanism

When PII is detected, the tool call is suspended until approval.

```rust
struct ApprovalManager {
    pending_approvals: Arc<RwLock<HashMap<ApprovalId, PendingApproval>>>,
    telegram_bot: TelegramBot,
    db: SqlitePool,
}

struct PendingApproval {
    approval_id: ApprovalId,
    tool_call: ToolCall,
    pii_detections: Vec<PIIDetection>,
    user_id: UserId,
    session_id: SessionId,
    requested_at: DateTime<Utc>,
    timeout_at: DateTime<Utc>,
    status: ApprovalStatus,
    response_tx: oneshot::Sender<ApprovalDecision>,
}

enum ApprovalStatus {
    Pending,
    Approved,
    Denied,
    TimedOut,
}

enum ApprovalDecision {
    Approve,
    Deny,
    ApproveAlways(PIIType),  // Don't ask again for this PII type
}

impl ApprovalManager {
    async fn request_approval(&self, ctx: &ScanContext, pii: Vec<PIIDetection>) 
        -> Result<ApprovalDecision> {

        let approval_id = Uuid::new_v4().to_string();
        let (tx, rx) = oneshot::channel();

        let timeout_duration = Duration::from_secs(300);  // 5 minutes

        let pending = PendingApproval {
            approval_id: approval_id.clone(),
            tool_call: ctx.tool_call.clone(),
            pii_detections: pii.clone(),
            user_id: ctx.user_id,
            session_id: ctx.session_id,
            requested_at: Utc::now(),
            timeout_at: Utc::now() + timeout_duration,
            status: ApprovalStatus::Pending,
            response_tx: tx,
        };

        // Store in pending map
        self.pending_approvals.write().unwrap()
            .insert(approval_id.clone(), pending);

        // Send Telegram message
        self.send_approval_request(&approval_id, &ctx.user_id, &pii).await?;

        // Wait for response with timeout
        match tokio::time::timeout(timeout_duration, rx).await {
            Ok(Ok(decision)) => {
                self.record_decision(&approval_id, &decision).await?;
                Ok(decision)
            },
            Ok(Err(_)) => {
                // Channel closed (shouldn't happen)
                self.handle_timeout(&approval_id).await
            },
            Err(_) => {
                // Timeout
                self.handle_timeout(&approval_id).await
            },
        }
    }

    async fn handle_timeout(&self, approval_id: &str) -> Result<ApprovalDecision> {
        let mut approvals = self.pending_approvals.write().unwrap();
        if let Some(pending) = approvals.get_mut(approval_id) {
            pending.status = ApprovalStatus::TimedOut;
        }

        // Default: deny on timeout (security-first approach)
        warn!("PII approval timeout for {}, denying by default", approval_id);
        Ok(ApprovalDecision::Deny)
    }
}
