            &message,
            keyboard,
        ).await?;

        Ok(())
    }

    fn build_keyboard(&self, approval_id: &str, pii: &[PIIDetection]) -> InlineKeyboard {
        let mut keyboard = InlineKeyboard::new();

        // Row 1: Approve / Deny
        keyboard.add_row(vec![
            InlineButton::callback("✅ Approve", format!("approve:{}", approval_id)),
            InlineButton::callback("❌ Deny", format!("deny:{}", approval_id)),
        ]);

        // Row 2: Approve Always (for each unique PII type)
        let unique_types: HashSet<_> = pii.iter().map(|p| &p.pii_type).collect();
        if unique_types.len() == 1 {
            let pii_type = unique_types.iter().next().unwrap();
            keyboard.add_row(vec![
                InlineButton::callback(
                    format!("✅ Always allow {}", pii_type.display_name()),
                    format!("approve_always:{}:{}", approval_id, pii_type.as_str())
                ),
            ]);
        }

        // Row 3: View details
        keyboard.add_row(vec![
            InlineButton::callback("🔍 View Full Details", format!("details:{}", approval_id)),
        ]);

        keyboard
    }
}
